<script lang="ts">
  import type { Admin } from './admin.svelte.js';
  import { count, date } from './api.js';
  import { Button } from '#lib/components/ui/button/index.js';
  import * as Card from '#lib/components/ui/card/index.js';
  import * as Menu from '#lib/components/ui/dropdown-menu/index.js';
  import { Badge } from '#lib/components/ui/badge/index.js';
  import { Progress } from '#lib/components/ui/progress/index.js';
  import { Separator } from '#lib/components/ui/separator/index.js';
  let { a }: { a: Admin } = $props();
</script>
<div class="grid gap-6 md:grid-cols-2 xl:grid-cols-3">
  {#each a.accounts as account}<Card.Root class="flex flex-col"><Card.Header><div class="flex flex-wrap justify-between gap-2"><Badge variant="outline">{account.provider === 'xai' ? 'Grok' : 'ChatGPT'}{account.plan ? ' · ' + account.plan : ''}</Badge><Badge variant={!account.enabled ? 'outline' : account.expiresAt <= Date.now() ? 'destructive' : 'secondary'}>{!account.enabled ? 'Disabled' : account.expiresAt <= Date.now() ? 'Needs refresh' : 'Active'}</Badge></div><Card.Title class="break-words pt-2">{account.label || account.name || (account.provider === 'xai' ? 'Grok subscription' : 'ChatGPT subscription')}</Card.Title><Card.Description class="break-all">{account.email || 'Email not available'}</Card.Description></Card.Header><Card.Content class="flex-1 space-y-5"><dl class="grid grid-cols-2 gap-4 text-sm">{#each [{ title: 'Token expires', value: date(account.expiresAt) }, { title: 'Grants, lifetime', value: count(account.selectionCount) }, { title: 'Plan', value: account.plan || 'Not reported' }, { title: 'Last selected', value: date(account.lastSelectedAt) }] as detail}<div><dt class="text-xs text-muted-foreground">{detail.title}</dt><dd class="mt-1">{detail.value}</dd></div>{/each}</dl><details class="text-sm"><summary class="cursor-pointer text-muted-foreground">Account details</summary><dl class="mt-3 space-y-2"><div><dt class="text-xs text-muted-foreground">Account ID</dt><dd class="break-all font-mono text-xs">{account.accountId}</dd></div>{#if account.name}<div><dt class="text-xs text-muted-foreground">Name</dt><dd>{account.name}</dd></div>{/if}<div><dt class="text-xs text-muted-foreground">Credentials updated</dt><dd>{date(account.updatedAt)}</dd></div></dl></details>
    {#if a.quotas[account.accountId]}{@const quota = a.quotas[account.accountId]}<Separator />{#if 'error' in quota}<p class="text-sm text-destructive" role="status">{quota.error}</p>{:else}<div class="space-y-4" aria-label="Subscription usage"><p class="text-xs text-muted-foreground">Account-wide limits · {date(quota.checkedAt)}</p>{#each [{ label: 'Current window', value: quota.primary }, { label: 'Longer window', value: quota.secondary }] as item}{#if item.value}<div class="space-y-2"><div class="flex justify-between gap-2 text-sm"><span>{item.label}</span><span>{item.value.usedPercent === null ? 'Not reported' : count(item.value.usedPercent) + '% used'}</span></div>{#if item.value.usedPercent !== null}<Progress value={item.value.usedPercent} aria-label={item.label} />{/if}{#if item.value.resetAt}<p class="text-xs text-muted-foreground">Resets {date(item.value.resetAt)}</p>{/if}</div>{/if}{/each}{#if !quota.primary && !quota.secondary}<p class="text-sm text-muted-foreground">No usage windows reported.</p>{/if}</div>{/if}{/if}
